import sys
data = sys.stdin.read().split()
n = int(data[0])
v = [int(x) for x in data[1:1 + n]]
total = sum(v)
best = None
if total % 2 == 0:
    for mask in range(1, 1 << n):
        idx = [i for i in range(n) if (mask >> i) & 1]
        if sum(v[i] for i in idx) * 2 == total:
            if best is None or idx < best:
                best = idx
if best is None:
    print('false')
else:
    print('true')
    print(' '.join(map(str, best)))

